These conditions involve true DGP parameters, which in practice must be estimated. The ASV framework (§\ref{sec:asv}) provides a complementary assessment that does not require knowledge of the exact sufficient conditions.

\subsection{Annotation Sensitivity Values}
\label{sec:asv}

We introduce Annotation Sensitivity Values (ASVs) as a unified sensitivity analysis framework, analogous to E-values for unmeasured confounding~\cite{vanderweele_ding2017} but designed for annotation-induced bias.

\paragraph{Parameterization.}
We parameterize the confusion matrix as $C(\delta) = (1{-}\delta)I + \delta C_0$, where $C_0$ is a reference confusion matrix (e.g., estimated from a validation set) and $\delta \geq 0$ controls the severity of misclassification. At $\delta{=}0$, classification is perfect; at $\delta{=}1$, classification matches $C_0$. Non-negativity of $C(\delta)$ requires $\delta \leq \delta_{\max} = \min_j \frac{1}{1 - (C_0)_{jj}}$. Since $(C_0)_{jj} \in [0,1]$, we have $\delta_{\max} \geq 1$ for all valid $C_0$, ensuring the full range $[0,1]$ is always feasible; all ASV computations are constrained to $[0, \delta_{\max}]$. In practice, $C_0$ is estimated from a finite validation set and subject to sampling uncertainty; we recommend bootstrapping $C_0$ and reporting ASV confidence intervals. The linear path $C(\delta)$ is the natural first-order approximation; alternative parameterizations (e.g., matrix exponential or Dirichlet-based paths) could capture nonlinear degradation but sacrifice the interpretability of $\delta$ as a scalar severity dial.

\paragraph{Three ASV types.}
We define three complementary measures: (1)~\textbf{Magnitude ASV} $\delta^*_{\text{mag}} = \min\{\delta : |\text{plim}\;\hat{\tau}(C(\delta)) - \tau| > \epsilon\}$---analogous to E-values; (2)~\textbf{Significance ASV} $\delta^*_{\text{sig}} = \min\{\delta : |\text{plim}\;\hat{\tau}(C(\delta))| < z_{\alpha/2} \cdot SE(N)\}$---relevant for attenuating topologies; (3)~\textbf{Sign-flip ASV} $\delta^*_{\text{sf}} = \min\{\delta : \text{sign}(\hat{\tau}) \neq \text{sign}(\tau)\}$---exposure and IV only. The significance ASV depends on $N$ through $SE(N)$, exhibiting a sharp phase transition at a critical $N^*$ below which all rejections are blocked.

\begin{theorem}[Envelope monotonicity---confounding and mediation]
\label{thm:monotone}
For confounding and mediation topologies with proportional effects ($f = \lambda g$ for some scalar $\lambda$) under $C(\delta) = (1{-}\delta)I + \delta C_0$, $|B(C(\delta))|$ is monotonically non-decreasing in $\delta \in [0, \delta_{\max}]$.
\end{theorem}

\emph{Proof sketch.} Both topologies reduce to $B(C(\delta)) {=} \lambda V_W(\delta)/(V_W(\delta) {+} \sigma^2)$ where $V_W(\delta) {=} \operatorname{Var}(g) {-} \operatorname{Var}(\mathbb{E}[g{\mid}A^*_\delta])$ and $\sigma^2$ is a topology-specific constant ($\sigma_T^2$ for confounding, $\mathbb{E}[\operatorname{Var}(T{\mid}A)]$ for mediation). As $\delta$ increases, $A^*$ becomes a noisier channel for $A$, so $\operatorname{Var}(\mathbb{E}[g{\mid}A^*_\delta])$ decreases by the data processing inequality, increasing $V_W$. Since $x/(x{+}c)$ is increasing for $c{>}0$, $|B|$ is non-decreasing (full proofs in Appendix~\ref{app:monotonicity_proof} and~\ref{par:med_monotone}). For general (non-proportional) effects, numerical verification across 10{,}000 random matrices confirms $\varepsilon$-approximate monotonicity with $\varepsilon < 0.02$ (Appendix~\ref{app:monotonicity_proof}).

\begin{conjecture}[$\varepsilon$-approximate envelope monotonicity]
\label{conj:monotone}
For the five remaining non-IV topologies under $C(\delta) = (1{-}\delta)I + \delta C_0$: exposure and front-door are $\varepsilon$-approximately non-decreasing in $\delta$, and collider and M-bias (protective topologies) are $\varepsilon$-approximately non-increasing in $\delta$, with $\varepsilon < 0.06$ ($<$6\% of $\tau$). Verified across 10{,}000 random matrices per topology and $K \in \{3,5,7\}$ using analytic probability limits (Appendix~\ref{sec:conjecture_verify}).
\end{conjecture}

The instrumental variable topology is excluded from Conjecture~\ref{conj:monotone}: the Wald estimator $\hat{\tau} = \hat{\gamma}_{Y{\sim}A^*} / \hat{\gamma}_{T{\sim}A^*}$ exhibits singularities when the first-stage coefficient passes through zero as $\delta$ increases, producing unbounded deviations ($>10^6$). This is a property of the Wald estimator itself, not of the ASV framework; magnitude ASV remains well-defined for IV away from first-stage singularities.

When strict monotonicity holds only approximately ($\varepsilon < 0.06$), the reported ASV threshold $\delta^*$ may differ from the true threshold by at most $\varepsilon/\eta$ in $\delta$-units, where $\eta$ is the practitioner's bias tolerance. At the recommended $\eta = 10\%$, this uncertainty is below 0.6 $\delta$-steps---negligible for practical sensitivity assessment. Topology rankings (which topologies are most fragile) are preserved across all tested configurations.

Binarization of $K{=}3$ annotations introduces additional topology-dependent bias (Appendix~\ref{app:binarization}).

\subsection{Mediation Topology ($A$ = Mediator)}
\label{app:mediation}

\paragraph{Data-generating process.}
$T\to A\to Y$, $T\to Y$.
\begin{align*}
  T &\sim \operatorname{Bernoulli}(0.5),\\
  A\mid T &\sim \operatorname{Categorical}\bigl(\operatorname{softmax}(\boldsymbol{\gamma}+\boldsymbol{\delta}\,T)\bigr),\\
  Y &= \tau_{\mathrm{dir}}\,T + f(A) + \varepsilon_Y.
\end{align*}

\paragraph{Bias decomposition.}
By Lemma~\ref{lem:bias_decomp}, the direct-effect estimator satisfies:
\begin{equation}
  \operatorname{plim}\hat\tau_{\mathrm{dir}}(C) = \tau_{\mathrm{dir}} + \frac{\mathbb{E}[\operatorname{Cov}(T,\,f(A)\mid A^*)]}{D(C)}.
  \label{eq:med_bias}
\end{equation}

The key structural difference from confounding: $T$ \emph{causes} $A$, so the residual covariance $\operatorname{Cov}(T,f(A)\mid A^*)$ captures the indirect effect of $T$ on $Y$ through $A$ that is not absorbed by conditioning on $A^*$.

\paragraph{Endpoint analysis.}

At $C=I$ ($A^*{=}A$): conditioning on $A$ blocks the mediated path $T\to A\to Y$, so $\operatorname{Cov}(T,f(A)\mid A)=0$ and $\operatorname{plim}\hat\tau=\tau_{\mathrm{dir}}$.

At $C=\frac{1}{K}\mathbf{1}\mathbf{1}^\top$ ($A^*\perp A$): no information about $A$ is used, and
\begin{align*}
  \mathbb{E}[\operatorname{Cov}(T,f(A)\mid A^*)] &= \operatorname{Cov}(T,f(A)),\\
  D(C) &= \operatorname{Var}(T) = 0.25.
\end{align*}
The indirect effect is $\tau_{\mathrm{ind}}=\mathbb{E}[f(A)\mid T{=}1]-\mathbb{E}[f(A)\mid T{=}0]$, and
\[
  \operatorname{Cov}(T,f(A)) = 0.25\,\tau_{\mathrm{ind}}.
\]
Hence at $C$ uniform: $\operatorname{plim}\hat\tau = \tau_{\mathrm{dir}}+\tau_{\mathrm{ind}} = \tau_{\mathrm{total}}$.

\paragraph{Empirical Finding (Mediation sign preservation).}
\label{find:med_sign}
$\operatorname{sign}(\operatorname{plim}\hat\tau_{\mathrm{dir}})=\operatorname{sign}(\tau_{\mathrm{dir}})$ whenever $\operatorname{sign}(\tau_{\mathrm{dir}})=\operatorname{sign}(\tau_{\mathrm{total}})$, where $\tau_{\mathrm{total}}=\tau_{\mathrm{dir}}+\tau_{\mathrm{ind}}$.
This result is verified numerically for $100{,}000$ independently sampled column-stochastic matrices $C$; a closed-form proof for general $K$ remains open.

\begin{proof}
Let $R(C)=\mathbb{E}[\operatorname{Cov}(T,f(A)\mid A^*)]$ and $D(C)=\mathbb{E}[\operatorname{Var}(T\mid A^*)]>0$.

\emph{Endpoints.}
At $C{=}I$: $f(A)$ is constant given $A{=}A^*$, so $R(I)=0$ and $B(I)=0$.
At $C=\frac{1}{K}\mathbf{1}\mathbf{1}^\top$: $R=\operatorname{Cov}(T,f(A))=0.25\,\tau_{\mathrm{ind}}$ and $D=\operatorname{Var}(T)=0.25$, giving $B=\tau_{\mathrm{ind}}$.

\emph{Within-group structure for binary $T$.}
Since $T\in\{0,1\}$, the within-$A^*$-group bias admits a revealing decomposition.
Let $p_j=P(T{=}1\mid A^*{=}j)$.
Then $\operatorname{Var}(T\mid A^*{=}j)=p_j(1{-}p_j)$ and
\[
  \operatorname{Cov}(T,f(A)\mid A^*{=}j)
  = p_j(1{-}p_j)\bigl[\mathbb{E}[f(A)\mid T{=}1,A^*{=}j]-\mathbb{E}[f(A)\mid T{=}0,A^*{=}j]\bigr].
\]
Define $\delta_j=\mathbb{E}[f(A)\mid T{=}1,A^*{=}j]-\mathbb{E}[f(A)\mid T{=}0,A^*{=}j]$ as the \emph{conditional indirect effect} in the $A^*{=}j$ subpopulation.
Then
\[
  B(C)=\frac{R(C)}{D(C)}
  =\frac{\sum_j q_j\,p_j(1{-}p_j)\,\delta_j}{\sum_j q_j\,p_j(1{-}p_j)}
  =\sum_j w_j\,\delta_j,
\]
a weighted average of the conditional indirect effects, with weights $w_j=q_j p_j(1{-}p_j)/\sum_\ell q_\ell p_\ell(1{-}p_\ell)\geq 0$ summing to 1.

At $C{=}I$: each $A^*{=}j$ group has $A{=}j$ a.s., so $\delta_j=f(j)-f(j)=0$ and $B=0$.
At $C$ uniform: $\delta_j=\tau_{\mathrm{ind}}$ for all $j$ and $B=\tau_{\mathrm{ind}}$.

\emph{Sign preservation.}
When $\operatorname{Cov}(g(A),f(A))>0$ (the indirect effect reinforces the direct effect, i.e., $\tau_{\mathrm{dir}}$ and $\tau_{\mathrm{ind}}$ have the same sign), the bias $B(C)\geq 0$ cannot oppose $\tau_{\mathrm{dir}}$, so sign is preserved trivially.

When $\tau_{\mathrm{dir}}$ and $\tau_{\mathrm{ind}}$ have opposite signs but $|\tau_{\mathrm{ind}}|<|\tau_{\mathrm{dir}}|$ (i.e., $\operatorname{sign}(\tau_{\mathrm{dir}})=\operatorname{sign}(\tau_{\mathrm{total}})$), sign reversal requires some $|\delta_j|>|\tau_{\mathrm{dir}}|$ with the opposing sign.
Since each $\delta_j$ is a difference of weighted averages of $f$ values (with weights $P(A{=}k\mid T{=}t,A^*{=}j)$), and $B(C)$ is a convex combination of $\delta_j$, the bound $|B(C)|\leq\max_j|\delta_j|$ holds.
We verify numerically that $\max_j|\delta_j|\leq|\tau_{\mathrm{ind}}|$ for all 100{,}000 random $C$ matrices in our experiments, confirming sign preservation.
\end{proof}

\paragraph{Verification for paper parameters ($K{=}3$).}
With $\tau_{\mathrm{dir}}{=}0.5$, $\boldsymbol{\gamma}{=}(0,0,0)$, $\boldsymbol{\delta}{=}(0,0.8,{-}0.6)$, $\boldsymbol{\beta}{=}(0,1.0,{-}0.5)$:

$\tau_{\mathrm{ind}}=\mathbb{E}[f(A)\mid T{=}1]-\mathbb{E}[f(A)\mid T{=}0]=0.351$ (computed from the softmax class probabilities).
$\tau_{\mathrm{total}}=0.5+0.351=0.851>0$.
Since $\tau_{\mathrm{dir}}{>}0$ and $\tau_{\mathrm{total}}{>}0$, sign preservation holds for all $C$.

\paragraph{Mediation monotonicity (proportional effects).}
\label{par:med_monotone}

Under the interpolation $C(\delta)=(1{-}\delta)I+\delta C_0$, we prove $|B(C(\delta))|$ is non-decreasing in $\delta$ when the mediator's effect on $Y$ is proportional to its informativeness about $T$: $f(A)=\lambda\,g(A)$ for some scalar $\lambda$, where $g(k)=\mathbb{E}[T\mid A{=}k]$.

\emph{Step 1: Decompose $T$ via the mediator.}
Define $g(A)=\mathbb{E}[T\mid A]$ and $\varepsilon_T = T - g(A)$.
By construction, $\mathbb{E}[\varepsilon_T\mid A]=0$.
By non-differential misclassification ($T\perp A^*\mid A$):
$\mathbb{E}[\varepsilon_T\mid A{=}k, A^*{=}j] = 0$,
so $\mathbb{E}[\varepsilon_T\mid A^*{=}j]=0$ and $\operatorname{Cov}(\varepsilon_T,\,g(A)\mid A^*{=}j)=0$ for every $j$.

\emph{Step 2: Reduce the numerator.}
Since $f=\lambda g$:
\begin{align*}
  R(C) &= \lambda\,\mathbb{E}[\operatorname{Var}(g(A)\mid A^*)] = \lambda\,V_W.
\end{align*}

\emph{Step 3: Constant additive term in denominator.}
\begin{align*}
  D(C) &= \mathbb{E}[\operatorname{Var}(T\mid A^*)]
       = V_W + \sigma_\varepsilon^2,
\end{align*}
where $\sigma_\varepsilon^2\equiv\mathbb{E}[\operatorname{Var}(\varepsilon_T\mid A^*)]$.
This is \emph{constant} (independent of $C$):
$\mathbb{E}[\operatorname{Var}(\varepsilon_T\mid A^*)]
  = \sum_k p_k\,\operatorname{Var}(T\mid A{=}k)
  = \mathbb{E}[\operatorname{Var}(T\mid A)]$,
where the equality uses column-stochasticity: $\sum_j q_j\,P(A{=}k\mid A^*{=}j)=p_k$.

\emph{Step 4: Closed form and monotonicity.}
$B(C) = \lambda\,V_W/(V_W+\sigma_\varepsilon^2)$,
structurally identical to confounding (Proposition~\ref{prop:conf_prop}) with $\sigma_\varepsilon^2$ playing the role of $\sigma_T^2$.
Since $V_W(\delta)$ is non-decreasing by DPI (same argument as \S\ref{app:monotonicity_proof}, Step~1) and $h(x)=|\lambda|x/(x+\sigma_\varepsilon^2)$ is increasing, $|B(C(\delta))|$ is non-decreasing.

